logger = logging.getLogger("flag_gems.istft")


# An inverse-transform frame f contributes windowed samples to output positions
# [f*hop, f*hop + n_fft). Instead of scatter-adding frames into the signal with
# atomics (the classic unfold_backward shape, which serializes badly on GCU and
# is banned by the coding rules anyway), each program OWNS a contiguous block of
# output samples and gathers the few covering frames per sample. The same walk
# also accumulates the squared-window envelope, and the block is normalized and
# stored in one pass: overlap-add + envelope + normalize fused into a single
# kernel launch that reads every frame element exactly once and writes every
# output sample exactly once (deterministic, no atomics, fp32 accumulation).
@libentry()
@triton.jit
def istft_oa_norm_kernel(
    frames_ptr,  # (channel, n_frames, n_fft) real frames, or the real view of
    # complex frames laid out (channel, n_frames, n_fft, 2) when IS_COMPLEX
    window_ptr,  # (n_fft,) real window, already centered into the n_fft frame
    out_ptr,  # (channel, n_out) real output, or its real view when IS_COMPLEX
    n_frames,
    n_fft,
    hop,
    start,  # first output sample in padded-signal coordinates
    n_out,  # number of output samples per channel to produce
    frames_stride0,  # element strides of the (real-viewed) frames tensor
    frames_stride1,
    out_stride0,  # element stride between channels of the (real-viewed) output
    IS_COMPLEX: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    channel = tl.program_id(1)

    t0 = start + pid * BLOCK
    offs = t0 + tl.arange(0, BLOCK)
    out_mask = offs < start + n_out

    acc_r = tl.zeros([BLOCK], dtype=tl.float32)
    acc_i = tl.zeros([BLOCK], dtype=tl.float32)
    envelope = tl.zeros([BLOCK], dtype=tl.float32)

    # Frame f covers padded samples [f*hop, f*hop + n_fft): it contributes to
    # sample t iff f*hop <= t < f*hop + n_fft, i.e. ceil((t-n_fft+1)/hop) <= f
    # <= t//hop. Only positive operands enter the divisions.
    first_covered = tl.maximum(t0 - n_fft + 1, 0)
    f_lo = (first_covered + hop - 1) // hop
    f_hi = tl.minimum((t0 + BLOCK - 1) // hop, n_frames - 1)
    frames_base = channel * frames_stride0

    for f in range(f_lo, f_hi + 1):
        j = offs - f * hop
        valid = (j >= 0) & (j < n_fft)
        frame_base = frames_base + f * frames_stride1
        w = tl.load(window_ptr + j, mask=valid, other=0.0).to(tl.float32)
        if IS_COMPLEX:
            fr = tl.load(frames_ptr + frame_base + 2 * j, mask=valid, other=0.0)
            fi = tl.load(frames_ptr + frame_base + 2 * j + 1, mask=valid, other=0.0)
            acc_r += fr.to(tl.float32) * w
            acc_i += fi.to(tl.float32) * w
        else:
            fr = tl.load(frames_ptr + frame_base + j, mask=valid, other=0.0)
            acc_r += fr.to(tl.float32) * w
        envelope += w * w

    y_r = acc_r / envelope
    t_off = offs - start
    if IS_COMPLEX:
        # out_stride0 is the real-view channel stride and already carries the
        # x2 interleave; only the within-sample offset multiplies by 2.
        y_i = acc_i / envelope
        addr = channel * out_stride0 + 2 * t_off
        tl.store(out_ptr + addr, y_r.to(out_ptr.dtype.element_ty), mask=out_mask)
        tl.store(out_ptr + addr + 1, y_i.to(out_ptr.dtype.element_ty), mask=out_mask)
    else:
        addr = channel * out_stride0 + t_off
        tl.store(out_ptr + addr, y_r.to(out_ptr.dtype.element_ty), mask=out_mask)


def istft(
    input,
    n_fft,
    hop_length=None,
    win_length=None,
    window=None,
    center=True,
    normalized=False,
    onesided=None,
    length=None,
    return_complex=False,
):
    logger.debug("GEMS_ENFLAME ISTFT")
    if hop_length is None:
        hop_length = n_fft // 4
    if win_length is None:
        win_length = n_fft

    if not input.is_complex():
        raise RuntimeError(
            "istft requires a complex-valued input tensor matching the "
            "output from stft with return_complex=True."
        )

    if input.dtype not in (torch.complex32, torch.complex64, torch.complex128):
        raise TypeError(
            "istft supports only complex32, complex64 and complex128 inputs, "
            f"got {input.dtype}"
        )

    inp = torch.view_as_real(input.resolve_conj())
    input_dim = inp.dim()
    n_frames = inp.shape[-2]
    fft_size = inp.shape[-3]
    if inp.numel() == 0:
        raise RuntimeError("istft: input tensor cannot be empty.")
    if input_dim not in (3, 4):
        raise RuntimeError(
            f"istft: expected a tensor with 3 or 4 dimensions, but got {input_dim}"
        )
    if inp.shape[-1] != 2:
        raise RuntimeError(
            f"istft: expected the last dimension to be 2, but got {inp.shape[-1]}"
        )

    if onesided is None:
        onesided = fft_size != n_fft
    if onesided:
        if n_fft // 2 + 1 != fft_size:
            raise RuntimeError(
                f"istft: expected the frequency dimension to match n_fft / 2 + 1 "
                f"when onesided=True, but got {fft_size}"
            )
    else:
        if n_fft != fft_size:
            raise RuntimeError(
                f"istft: expected the frequency dimension to match n_fft when "
                f"onesided=False, but got {fft_size}"
            )
    if not (0 < hop_length <= win_length):
        raise RuntimeError("istft: expected 0 < hop_length <= win_length")
    if not (0 < win_length <= n_fft):
        raise RuntimeError("istft: expected 0 < win_length <= n_fft")
    if window is not None and (window.dim() != 1 or window.shape[0] != win_length):
        raise RuntimeError(
            "istft: Invalid window shape. window has to be 1D and length of "
            "`win_length`"
        )

    # Frame data as complex (channel, n_frames, fft_size); cuFFT requires
    # contiguous input.
    frames = input.resolve_conj().transpose(-1, -2)  # (..., n_frames, fft_size)
    if input_dim == 3:
        frames = frames.unsqueeze(0)
    channel = frames.shape[0]
    frames = frames.contiguous()

    norm = "ortho" if normalized else "backward"
    if return_complex:
        if onesided:
            raise RuntimeError(
                "istft: cannot have onesided output if window or input is complex"
            )
        frames_t = torch.fft.ifft(frames, n=n_fft, dim=-1, norm=norm)
        real_out = False
    else:
        if not onesided:
            frames = frames[..., : n_fft // 2 + 1]
        # c2r inverse writes a real (channel, n_frames, n_fft) tensor.
        frames_t = torch.fft.irfft(frames, n=n_fft, dim=-1, norm=norm)
        real_out = True

    # Window: mirror torch's centering of the window into the n_fft frame.
    # Real component dtype of the complex spectrum (complex32 -> float16,
    # complex64 -> float32, complex128 -> float64).
    _real_of_complex = {
        torch.complex32: torch.float16,
        torch.complex64: torch.float32,
        torch.complex128: torch.float64,
    }
    out_real_dtype = _real_of_complex.get(input.dtype, torch.float32)
    if window is None:
        window_full = torch.ones(n_fft, dtype=out_real_dtype, device=frames_t.device)
    elif win_length != n_fft:
        left = (n_fft - win_length) // 2
        window_full = torch.constant_pad_nd(
            window, (left, n_fft - win_length - left), 0.0
        ).to(out_real_dtype)
    else:
        window_full = window.to(out_real_dtype)

    expected_len = n_fft + hop_length * (n_frames - 1)
    start = n_fft // 2 if center else 0
    if length is not None:
        end = start + length
    elif center:
        end = expected_len - n_fft // 2
    else:
        end = expected_len
    n_out = max(min(end, expected_len) - start, 0)

    if frames_t.numel() > 2147483647:
        raise RuntimeError("istft: input is too large for int32 addressing")

    if n_out > 0:
        if real_out:
            out = torch.empty(
                channel, n_out, dtype=out_real_dtype, device=frames_t.device
            )
            frames_view = frames_t
        else:
            out = torch.empty(
                channel,
                n_out,
                dtype=frames_t.dtype,
                device=frames_t.device,
            )
            frames_view = torch.view_as_real(frames_t)
        out_view = out if real_out else torch.view_as_real(out)

        # Two-tier tile: tiny outputs are launch-bound and favor a small
        # block (measured on GCU400), while every larger shape prefers the
        # widest block because each program then walks fewer frame-overlap
        # iterations per output sample.
        BLOCK = 256 if channel * n_out <= 8192 else 1024
        grid = (triton.cdiv(n_out, BLOCK), channel)
        istft_oa_norm_kernel[grid](
            frames_view,
            window_full,
            out_view,
            n_frames,
            n_fft,
            hop_length,
            start,
            n_out,
            frames_view.stride(0),
            frames_view.stride(1),
            out_view.stride(0),
            IS_COMPLEX=not real_out,
            BLOCK=BLOCK,
        )
    else:
        out = torch.empty(channel, 0, dtype=out_real_dtype, device=frames_t.device)

    if end > expected_len:
        pad = end - expected_len
        out = torch.constant_pad_nd(out, (0, pad), 0.0)
    if input_dim == 3:
        out = out.squeeze(0)
    return out
